cd /home/dev/garden && python3 -c "
import json
m=json.load(open('bench/results/2026-10-12/m1-ngram/replay_manifest.json'))
print('== baseline-r0/0/* manifest entries (in order) ==')
for req in sorted(m['requests'], key=lambda r: r['id']):
    if req.get('id','').startswith('inventory-baseline-r0/0/'):
        print(req['id'], req.get('recorded_prompt_tokens'), 'chars=',req.get('prompt_chars'), 'cbrole=',req.get('chars_by_role'))
print()
print('== inventory baseline-r0 step0 agent tap totals (prompt_n, cache_n, predicted_n) ==')
inv=json.load(open('bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
for run in inv['runs']:
    if run['run_id']=='inventory-baseline-r0':
        for idx, rec in enumerate(run['steps']['0']['tap_records']):
            tot = rec['prompt_n']+rec['cache_n']
            print('req%d n_messages=%d  prompt_n=%d cache_n=%d predicted_n=%d  total=%d' % (idx, rec['n_messages'], rec['prompt_n'], rec['cache_n'], rec['predicted_n'], tot))
"

